RIDES = [('Outlaw Run', 'thrill coaster'), ('Time Traveler', 'thrill coaster'), ('Powder Keg', 'thrill coaster'), ('Fire In The Hole', 'family coaster'), ('Mystic River Falls', 'water ride')]
print('Ride-type classifier: Silver Dollar City')
counts = {}
for name, kind in RIDES:
    counts[kind] = counts.get(kind, 0) + 1
for kind in sorted(counts):
    print("%s: %d" % (kind, counts[kind]))
print("Operating rides classified: %d" % len(RIDES))

